import{_ as n,C as o,c as s,o as r,a3 as t,G as i}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Payments overview","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/payments/index.md","filePath":"master/finance/payments/index.md","lastUpdated":1791902625000}'),l={name:"master/finance/payments/index.md"};function m(h,e,c,d,p,u){const a=o("ImagePopup");return r(),s("div",null,[e[0]||(e[0]=t('<h1 id="payments-overview" tabindex="-1">Payments overview <a class="header-anchor" href="#payments-overview" aria-label="Permalink to &quot;Payments overview&quot;">​</a></h1><p>A payment is the record that money moved. It can come in from a customer or go out to a vendor. When you link a payment to an invoice or a bill, the open balance goes down and the document is settled.</p><p>This section explains how to pay an invoice or bill, how to manage the payments list, and how to keep bank accounts.</p><blockquote><p><strong>In simple words:</strong> An invoice says who owes money. A payment says the money was paid. Aureus links the two for you.</p></blockquote><h2 id="how-a-payment-settles-a-document" tabindex="-1">How a payment settles a document <a class="header-anchor" href="#how-a-payment-settles-a-document" aria-label="Permalink to &quot;How a payment settles a document&quot;">​</a></h2><p>Follow this path for a customer invoice:</p><ol><li>You confirm the invoice. It is <strong>Posted</strong> and the <strong>Payment State</strong> is <strong>Not paid</strong>.</li><li>You click <strong>Pay</strong> on the invoice and fill in the <strong>Pay</strong> window.</li><li>Aureus creates a payment, posts its journal entry and links it to the invoice.</li><li>The <strong>Amount Due</strong> on the invoice goes down. The <strong>Payment State</strong> changes.</li></ol><p>A bill works the same way, with money going out instead of in. See <a href="./register-payment.html">Register a payment</a> for the full steps.</p><h2 id="customer-and-vendor-payments" tabindex="-1">Customer and vendor payments <a class="header-anchor" href="#customer-and-vendor-payments" aria-label="Permalink to &quot;Customer and vendor payments&quot;">​</a></h2><p>Every payment has a <strong>Payment Type</strong>.</p><ul><li><strong><em>Receive:</em></strong> Money comes in from a customer. You create it from an invoice, or from <code>Customers → Payments</code>.</li><li><strong><em>Send:</em></strong> Money goes out to a vendor. You create it from a bill, or from <code>Vendors → Payments</code>.</li></ul><p>The menu path exists in both apps:</p><ul><li><code>Invoices → Customers → Payments</code> and <code>Invoices → Vendors → Payments</code></li><li><code>Accounting → Customers → Payments</code> and <code>Accounting → Vendors → Payments</code></li></ul><p>Both apps show the same screens and the same data.</p><h2 id="payment-status" tabindex="-1">Payment status <a class="header-anchor" href="#payment-status" aria-label="Permalink to &quot;Payment status&quot;">​</a></h2><p>The payment itself has a status. You see it in the <strong>State</strong> column of the payments list.</p><ul><li><strong>Draft:</strong> The payment is saved but not confirmed. It has no journal entry yet.</li><li><strong>In Process:</strong> The payment is confirmed and posted. The money is on its way.</li><li><strong>Paid:</strong> The payment is complete. A payment from a cash journal goes straight to this status.</li><li><strong>Not Paid:</strong> The payment is posted but the money is not received or sent.</li><li><strong>Cancelled:</strong> The payment was cancelled while still a draft.</li></ul><p>See <a href="./manage-payments.html">Manage payments</a> for the buttons that change the status.</p><h2 id="payment-state-on-the-invoice-or-bill" tabindex="-1">Payment State on the invoice or bill <a class="header-anchor" href="#payment-state-on-the-invoice-or-bill" aria-label="Permalink to &quot;Payment State on the invoice or bill&quot;">​</a></h2><p>The document has its own field, <strong>Payment State</strong>. It tells you how much is settled.</p><ul><li><strong>Not paid:</strong> Nothing is paid yet.</li><li><strong>In Payment:</strong> A payment is registered and posted, and the money is on its way.</li><li><strong>Partial:</strong> Some money is paid and an <strong>Amount Due</strong> is left.</li><li><strong>Paid:</strong> The <strong>Amount Due</strong> is zero.</li><li><strong>Reversed:</strong> A credit note or refund cancelled the document.</li></ul><p>Do not mix the two fields. The payment has a <strong>State</strong>. The document has a <strong>Payment State</strong>.</p><h2 id="partial-payments" tabindex="-1">Partial payments <a class="header-anchor" href="#partial-payments" aria-label="Permalink to &quot;Partial payments&quot;">​</a></h2><p>You do not have to pay everything at once. In the <strong>Pay</strong> window, enter a smaller <strong>Amount</strong>. The document becomes <strong>Partial</strong> and the <strong>Amount Due</strong> shows the rest. Pay again later to close it.</p><h2 id="two-ways-to-create-a-payment" tabindex="-1">Two ways to create a payment <a class="header-anchor" href="#two-ways-to-create-a-payment" aria-label="Permalink to &quot;Two ways to create a payment&quot;">​</a></h2><ol><li><strong>From the document.</strong> Open a posted invoice or bill and click <strong>Pay</strong>. The payment is linked to the document at once. Use this in most cases.</li><li><strong>From the list.</strong> Open the Payments list and click <strong>New</strong>. Use this for a payment you want to enter first and match later.</li></ol><h2 id="example-flow" tabindex="-1">Example flow <a class="header-anchor" href="#example-flow" aria-label="Permalink to &quot;Example flow&quot;">​</a></h2><p>Invoice INV/2026/2 for Deco Addict is posted for 891.25.</p><ol><li>You click <strong>Pay</strong> and enter 891.25 with a bank journal.</li><li>Aureus creates the payment PBANK/2026/3.</li><li>The <strong>Amount Due</strong> falls to 0.00 and the <strong>Payment State</strong> becomes <strong>Paid</strong>.</li><li>The <strong>Payments</strong> tab of the invoice lists PBANK/2026/3.</li></ol><h2 id="where-to-find-payments" tabindex="-1">Where to find payments <a class="header-anchor" href="#where-to-find-payments" aria-label="Permalink to &quot;Where to find payments&quot;">​</a></h2><ul><li><strong>On an invoice or bill:</strong> Open the <strong>Payments</strong> tab. It lists the payments linked to that document.</li><li><strong>In the list:</strong> Open <code>Customers → Payments</code> or <code>Vendors → Payments</code>. The list has views for <strong>Customer Payments</strong>, <strong>Vendor Payments</strong>, <strong>Draft</strong> and <strong>In Process</strong>.</li><li><strong>In the accounting entries:</strong> Each payment has a journal entry. See <a href="./../accounting-entries/journal-entries.html">Journal entries</a> and <a href="./../accounting-entries/journal-items.html">Journal items</a>. These are in the Accounting app only.</li></ul>',31)),i(a,{src:"/images1/finance/payments_list_overview.png",alt:"The Payments list at Customers → Payments showing the payment for Deco Addict, 891.25, status In Process"}),e[1]||(e[1]=t('<h2 id="in-this-section" tabindex="-1">In this section <a class="header-anchor" href="#in-this-section" aria-label="Permalink to &quot;In this section&quot;">​</a></h2><ul><li><a href="./register-payment.html">Register a payment</a>: use the <strong>Pay</strong> window on an invoice or bill.</li><li><a href="./manage-payments.html">Manage payments</a>: the list, the form and the status buttons.</li><li><a href="./bank-accounts.html">Bank accounts</a>: store the bank details of your partners.</li><li>Payment numbers come from a payment sequence. See <a href="./../../general-settings/customization/sequences.html">Sequences</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../customer-invoices/create-invoice.html">Create an invoice</a></li><li><a href="./../vendor-bills/create-bill.html">Create a bill</a></li><li><a href="./../get-started/journals.html">Journals</a></li></ul>',4))])}const f=n(l,[["render",m]]);export{y as __pageData,f as default};
